def main():
    src = PATCH.read_text(encoding="utf-8")
    tree = ast.parse(src)
    edits_node = None
    for n in tree.body:
        if isinstance(n, ast.Assign) and len(n.targets) == 1 \
                and isinstance(n.targets[0], ast.Name) and n.targets[0].id == "EDITS":
            edits_node = n.value
            break
    assert edits_node is not None
    # 各タプルのソース範囲を収集する（後ろから置き換えるため降順にする）。
    spans = []
    for elt in edits_node.elts:
        name = ast.literal_eval(elt.elts[0])
        seg = ast.get_source_segment(src, elt)
        spans.append((elt.end_lineno, elt.end_col_offset, name, seg))
    spans.sort(reverse=True)
    by_name = {name: seg for _, _, name, seg in spans}
    failed = []
    for name in FIX_EDITS_FULL_774_IDS:
        if name not in by_name:
            failed.append(f"{name}: EDITS に存在しない")
    if failed:
        print("失敗:", file=sys.stderr)
        for f in failed:
            print(" -", f, file=sys.stderr)
        sys.exit(1)
    changed = 0
    for _, _, name, seg in spans:
        if name not in FIX_EDITS_FULL_774_IDS:
            continue
        want_old, want_new = FIX_EDITS_FULL_774_IDS[name]
        cur = ast.literal_eval(seg)
        if cur[1] == want_old and cur[2] == want_new:
            continue  # 既に適用済み
        new_seg = repr((name, want_old, want_new))
        # 元のタプルの範囲を new_seg で置き換える。
        start = seg_start(src, seg)
        end = start + len(seg)
        src = src[:start] + new_seg + src[end:]
        changed += 1
    PATCH.write_text(src, encoding="utf-8")
    print(f"patch-proxysession-774.py の EDITS {changed} 件を書き直した。")


def seg_start(src, seg):
    """seg の最初の出現位置を返す（EDITS 内のタプルは一意のはず）。"""
    i = src.find(seg)
    assert i >= 0
    return i


if __name__ == "__main__":
    main()
